import { expect, expectStatus, test, type Document } from "../../fixtures";

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in review whose insurance certificate expired yesterday.
  // The sample certificate expires in 2027, so this one is written here with yesterday's date.
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const vendor = await factory.vendor();
  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const certificate = [
    "Insurer: Harbor Mutual",
    "Policy Number: HM-55-1290",
    "Coverage Amount: $2,000,000",
    `Expiry Date: ${yesterday}`,
  ].join("\n");

  await factory.upload(vendor.id, "w9");
  await factory.upload(vendor.id, "contract");
  const uploaded = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "insurance_certificate",
      file: { name: "insurance_certificate.txt", mimeType: "text/plain", buffer: Buffer.from(certificate) },
    },
  });
  const { id: certificateId } = await expectStatus<Document>(uploaded, 201);

  await expect
    .poll(
      async () => {
        const documents = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
        return documents.map((d) => d.status).sort();
      },
      { message: "extraction finishes for all three documents", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);
  await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  const extraction = await factory.extraction(certificateId, "member");
  expect(extraction.status).toBe("pending_review");

  // Act: the reviewer approves the insurance certificate extraction
  const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert: the expiry check is flaky in CI, so only a non-server-error status is asserted
  expect(response.status(), await response.text()).toBeLessThan(500);
});
